  function selectLocalFiles(chosen:File[]){void preparePhotoFiles(chosen);}
  async function verifyQueued(fileKey:string){
    const q=queueRef.current,item=q?.items.find(i=>i.key===fileKey);if(!q||!item?.attemptId||!item.uploadId||requestRunning.current)return;
    requestRunning.current=true;checkingReadback.current=true;setBusy(true);setError('','upload');const token={scopeKey:q.scopeKey,key:item.key,attemptId:item.attemptId};const alive=()=>mounted.current&&queueRef.current?.scopeKey===q.scopeKey&&selectedRecord.current===q.recordId;
    try{const status=await api<UploadRow>(`${base}/${q.recordId}/uploads/${item.uploadId}`);if(!alive())return;if(status.state==='cancelled'){removeQueueUpload(item.uploadId);if(uploadPending?.uploadId===item.uploadId)saveUpload(null);setMessage('原上传已由服务器确认取消，请重新选择需要保存的原件。');return;}if(status.name!==item.name||(status.byteCount??status.byte_count)!==item.size||status.sha256!==item.sha256||(item.stepId&&(status.stepId||'')!==item.stepId))throw Error('服务器上传凭据与原件不一致，请保留凭据并重新核对');if(status.state!=='completed'){queueEvent({type:'failure',...token,error:'服务器尚未完成保存，请重新选择原件继续原上传。'});throw Error('服务器尚未完成保存，请继续原上传');}const fresh=await refreshDetail(q.recordId);if(!alive())return;const next=queueEvent({type:'saved',...token,receipt:{id:status.fileId||'',state:status.state,sha256:status.sha256},readback:{recordId:fresh.record.id,file:fresh.files.find(f=>f.id===status.fileId)}});if(next?.items.find(i=>i.key===fileKey)?.phase!=='saved')throw Error('完成凭据与原件列表不一致，请保留凭据并重新核对');if(uploadPending?.uploadId===item.uploadId)saveUpload(null);originalFiles.current.delete(fileKey);setFiles(Array.from(originalFiles.current.values()));setMessage('原件已重新读回并核对保存。');}
    catch(e){if(!alive())return;const current=queueRef.current?.items.find(i=>i.key===fileKey);if(current?.phase==='verifying')queueEvent({type:'failure',...token,resultUnconfirmed:true,error:(e as Error).message});setError((e as Error).message,'upload');}
    finally{requestRunning.current=false;checkingReadback.current=false;if(mounted.current)setBusy(false);}
  }
  async function upload(event: FormEvent){event.preventDefault();await runUploads();}
