        if(current&&(current.name!==file.name||current.byteCount!==file.size||current.sha256!==digest))throw Error('所选原件与上次文件不同，请重新选择同一摘要原件；原凭据保留');
        if(!current){const fresh=await refreshDetail(recordId);if(!alive())return;current={recordId,queueKey:item.key,name:file.name,mime:fileMime(file.name),byteCount:file.size,sha256:digest,requestId:crypto.randomUUID(),version:fresh.version,...(stepCategory?{stepId:item.stepId||uploadStep}:{})};saveUpload(current);}
        const uploadPath=`${base}/${recordId}/uploads`;
        if(!current.uploadId){starting=true;queueEvent({type:'start-request',...token});const result=await api<UploadRow>(uploadPath,'POST',{requestId:current.requestId,version:current.version,name:current.name,mime:current.mime,byteCount:current.byteCount,sha256:current.sha256,...(current.stepId?{stepId:current.stepId}:{})});if(!alive())return;if(!uuid(result.id))throw Error('服务未返回上传凭据');current={...current,uploadId:result.id};saveUpload(current);queueEvent({type:'progress',...token,phase:'uploading',bytes:0,sha256:digest,uploadId:result.id});starting=false;}
