        const fresh=await refreshDetail(recordId);if(!alive())return;const next=queueEvent({type:'saved',...token,receipt,readback:{recordId:fresh.record.id,file:fresh.files.find(f=>f.id===receipt.id)}});
        if(next?.items.find(i=>i.key===item.key)?.phase!=='saved')throw Error('服务端完成凭据与原件读回未一致，请重新核对保存结果');
        saveUpload(null);current=null;completed++;awaiting=false;originalFiles.current.delete(item.key);setFiles(Array.from(originalFiles.current.values()));await refreshAll(recordId);
